import{_ as e,a,o as r,a2 as o}from"./chunks/framework.DCcmcJcL.js";const m=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/introduction.md","filePath":"getting-started/introduction.md","lastUpdated":1789395222000}'),n={name:"getting-started/introduction.md"};function i(s,t,d,c,l,h){return r(),a("div",null,t[0]||(t[0]=[o('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p><a href="https://bagisto.com/en/" target="_blank" rel="noreferrer">Bagisto</a> is a free, open-source eCommerce platform for building and running online stores. It is released under the MIT license and built on the <a href="https://laravel.com/" target="_blank" rel="noreferrer">Laravel</a> framework, with <a href="https://vuejs.org/" target="_blank" rel="noreferrer">Vue.js</a> and <a href="https://tailwindcss.com/" target="_blank" rel="noreferrer">Tailwind CSS</a> powering a fast, responsive admin panel and storefront.</p><p>This guide is for merchants and store administrators. It shows you how to set up and run a Bagisto store from the admin panel, with no coding required. If you are building extensions, integrations or themes, see the <a href="https://devdocs.bagisto.com/" target="_blank" rel="noreferrer">developer documentation</a> instead.</p><h2 id="what-you-can-do-with-bagisto" tabindex="-1">What you can do with Bagisto <a class="header-anchor" href="#what-you-can-do-with-bagisto" aria-label="Permalink to &quot;What you can do with Bagisto&quot;">​</a></h2><ul><li><strong>Sell any kind of product</strong> – simple, configurable, virtual, downloadable, grouped, bundle and booking products, organized with categories, attributes and attribute families.</li><li><strong>Run several storefronts from one admin panel</strong> – each channel has its own domain, theme, root category, languages and currencies.</li><li><strong>Sell internationally</strong> – 22 languages with right-to-left support, multiple currencies and exchange rates.</li><li><strong>Manage stock across locations</strong> – track inventory across warehouses and stores.</li><li><strong>Handle every order</strong> – invoices, shipments, refunds, returns (RMA) and EU withdrawal requests.</li><li><strong>Promote your store</strong> – catalog and cart rules, coupons, email campaigns, sitemaps and search optimization.</li><li><strong>Create content with Generative AI (Magic AI)</strong> – draft product descriptions, generate product images, translate reviews and more.</li><li><strong>Design your storefront</strong> – choose a theme for each channel and build its pages from sections with a live preview.</li><li><strong>Keep your team secure</strong> – admin users, roles with granular permissions and two-factor authentication.</li><li><strong>Measure performance</strong> – sales, customer and product reports.</li></ul><h2 id="how-this-guide-is-organized" tabindex="-1">How this guide is organized <a class="header-anchor" href="#how-this-guide-is-organized" aria-label="Permalink to &quot;How this guide is organized&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Section</th><th>What it covers</th></tr></thead><tbody><tr><td><strong>Getting Started</strong></td><td>This introduction, the <a href="./command-palette.html">command palette</a> and <a href="./../authentication/2fa-authentication.html">two-factor authentication</a>.</td></tr><tr><td><a href="./../generative-ai/introduction.html">Generative AI</a></td><td>The AI features built into Bagisto and how to use each one.</td></tr><tr><td><a href="./../appearance/themes.html">Theme</a></td><td>Choosing a theme and customizing your storefront with sections.</td></tr><tr><td><a href="./../settings/channels.html">Store Setup</a></td><td>Channels, languages, currencies, inventory, taxes, team access and data imports.</td></tr><tr><td><a href="./../configure/introduction.html">Configure</a></td><td>Store-wide settings, from shipping, payment and checkout to email, search engines and caching.</td></tr><tr><td><a href="./../category/create-category.html">Catalog</a></td><td>Categories, attributes and every product type.</td></tr><tr><td><a href="./../customer/create-customer.html">Customers</a></td><td>Customer accounts, groups, group pricing and reviews.</td></tr><tr><td><a href="./../orders/create-order.html">Sales</a></td><td>Orders, invoices, shipments, refunds, returns, and shipping and payment methods.</td></tr><tr><td><a href="./../marketing/cart-rules.html">Marketing</a></td><td>Promotions, email communications and search engine optimization.</td></tr><tr><td><a href="./../cms/create-cms.html">CMS</a></td><td>Content pages such as About Us or your returns policy.</td></tr><tr><td><a href="./../reporting/sales-report.html">Reporting</a></td><td>Sales, customer and product reports.</td></tr></tbody></table><p>The extensions — <a href="./../b2b-marketplace/introduction.html">B2B Marketplace</a>, <a href="./../multi-tenant-ecommerce/introduction.html">Multi Tenant Ecommerce</a>, the <a href="./../b2b-ecommerce-platform/introduction.html">B2B eCommerce Platform</a> and the <a href="./../open-source-mobile-app/open-source-mobile-app.html">Native Mobile App</a> — are covered at the end of the guide.</p><h2 id="before-you-begin" tabindex="-1">Before you begin <a class="header-anchor" href="#before-you-begin" aria-label="Permalink to &quot;Before you begin&quot;">​</a></h2><p>You manage your store from the admin panel. On a standard installation it is at <code>/admin</code> on your store&#39;s domain, for example <code>https://your-store.com/admin</code>; whoever installed the store can move it to a different path.</p><p>Press <strong>Ctrl + K</strong> (<strong>⌘ K</strong> on a Mac) on any admin page to open the <a href="./command-palette.html">command palette</a> and jump straight to a menu item, a configuration screen, an action or a record.</p>',11)]))}const g=e(n,[["render",i]]);export{m as __pageData,g as default};
